import {regionMatches,findRegions} from '/assets/region-model.2d29e99c941f51c2.js';
import {displayName} from '/assets/aniimo-model.f4a49d2696e16024.js';
import {share} from '/assets/team-model.236e085dbfd8cffc.js';
const root=document.querySelector('[data-region-explorer]'),c=JSON.parse(root.querySelector('.region-config').textContent),{q,labels,lang,prefix}=c,$=s=>root.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,records,byId,region='breezy-plains',limit=20;const name=r=>(r.localizedNames[lang]||r.officialName).replace(/\s+/g,' ');
function filters(){return {region,elements:[...$('[data-filter=elements]').selectedOptions].map(o=>o.value),roles:[...$('[data-filter=roles]').selectedOptions].map(o=>o.value),form:$('[data-filter=form]').value,completeness:$('[data-filter=completeness]').value};}
function results(){if(!records)return;const f=filters(),matches=records.filter(r=>regionMatches(r,byId.get(r.entityId),f));$('.region-status').textContent=q.count+': '+matches.length;$('.region-results').innerHTML=matches.length?matches.slice(0,limit).map(r=>{const a=byId.get(r.entityId);return `<article class="region-form" data-entity="${r.entityId}"><img src="${esc(a.imageUrl)}" alt="${esc(displayName(r,lang,q.unknown))}" loading="lazy" width="160" height="160"><p class="region-image-fallback" hidden>${esc(q.imageUnavailable)}</p><h3>${esc(displayName(r,lang,q.unknown))}</h3><p>${esc(r.entryNo)} · ${esc(labels.formLabels[r.formType])}</p><p>${esc(r.elements.map(v=>labels.elementLabels[v]||v).join(' / '))} · ${esc(r.roles.map(v=>labels.roleLabels[v]||v).join(' / '))}</p><a href="${prefix}/guides/confirmed-aniimo/#entity=${r.entityId}">${esc(q.details)}</a></article>`;}).join(''):`<p>${esc(q.noResults)} ${esc(region==='unknown'?q.collectionNote:q.noMembers)}</p>`;$('.region-more').hidden=matches.length<=limit;const link=$('.region-team');if(link){link.hidden=!matches.length;link.href=prefix+'/team-builder/'+share({memberIds:matches.map(r=>r.entityId)});}}
function select(id,focus=false){if(!data)return;region=id;limit=20;root.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.region===id)));const r=data.regions.find(r=>r.regionId===id),panel=$('.region-detail');panel.innerHTML=r?`<p class="label">${esc(r.officialName)} · ${esc(r.regionType)}</p><h2 id="region-heading">${esc(name(r))}</h2><p>${esc(q.summary)}</p><p>${esc(r.description[lang])}</p><h3>${esc(q.environment)}</h3><p>${esc(r.description[lang])}</p>${r.children.length?`<p>${r.children.map(id=>{const child=data.regions.find(x=>x.regionId===id);return `<button data-region="${id}" type="button">${esc(name(child))}</button>`;}).join(' ')}</p>`:''}${r.representativeFamilies.length?`<h3>${esc(q.representatives)}</h3><p>${esc(r.representativeFamilies.join(' / '))}</p><p>${esc(q.noMembers)}</p>`:''}${r.regionId==='crescent-bay'?'<p>Mirrorsea Village · Sub-location</p>':''}<h3>${esc(q.stories)}</h3>${r.stories.map(s=>`<p><a href="${esc(s.sourceUrl)}" target="_blank" rel="nofollow noopener">${esc(s.name)}</a><br>${esc(q.published)} <time>${s.publishedAt}</time> · ${esc(q.updateDate)} ${s.updateDate}</p>`).join('')}${data.nonGeographic.filter(e=>e.regionType==='event-location'&&e.announcementMapRegionId===r.regionId).map(e=>`<p>${esc(q.eventNote)}<br>${esc(e.officialName)} · ${esc(e.mentionedForm)}<br>${esc(q.eventPeriod)} <time>${esc(e.eventStartLocal)}</time> → <time>${esc(e.eventEndLocal)}</time> (Europe UTC+0 / Americas UTC−4 / APAC UTC+8)<br><a href="${esc(e.sourceUrl)}" target="_blank" rel="nofollow noopener">${esc(q.source)} · ${esc(q.published)} 2026-10-27</a></p>`).join('')}<h3>${esc(q.guides)}</h3><p>${esc(q.guideHint)}</p><p>${r.guides.map(id=>`<a href="${prefix}/guides/${id}/">${esc(c.guideTitles[id])}</a>`).join(' ')}</p><p><a href="${esc(r.sourceUrl)}" target="_blank" rel="nofollow noopener">${esc(q.source)}</a> · ${esc(q.verified)} ${r.verifiedAt}</p><a class="region-team" hidden>${esc(q.team)}</a>`:`<h2 id="region-heading">${esc(q.unknown)}</h2><p>${esc(q.collectionNote)}</p><a class="region-team" hidden>${esc(q.team)}</a>`;results();if(focus)panel.focus();}
async function load(){root.dataset.ready='false';$('.region-retry').hidden=true;try{const values=await Promise.all([c.regions,c.characters].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error();return r.json();}));[data,records]=values;byId=new Map(data.associations.map(a=>[a.entityId,a]));if(records.length!==130||records.some(r=>!byId.has(r.entityId)))throw Error();select(region);root.dataset.ready='true';}catch{$('.region-status').textContent=q.noResults;$('.region-retry').hidden=false;}}
root.addEventListener('click',e=>{const b=e.target.closest('[data-region]');if(b)select(b.dataset.region,true);if(e.target.closest('[data-reset]')){root.querySelectorAll('[data-filter] option').forEach(o=>o.selected=false);$('[data-filter=form]').value='';$('[data-filter=completeness]').value='';$('.region-search').value='';search();limit=20;results();}if(e.target.closest('.region-more')){limit+=20;results();}});root.addEventListener('change',e=>{if(e.target.matches('[data-filter]')){limit=20;results();}});function search(){const ids=new Set(findRegions(data?.regions||[],$('.region-search').value).map(r=>r.regionId));root.querySelectorAll('.region-navigation [data-region]').forEach(b=>b.hidden=b.dataset.region==='unknown'?!!$('.region-search').value:!ids.has(b.dataset.region));}$('.region-search').addEventListener('input',search);$('.region-retry').addEventListener('click',load);root.addEventListener('error',e=>{if(e.target.matches('.region-form img')){e.target.hidden=true;e.target.nextElementSibling.hidden=false;}},true);load();
